CREATE OR REPLACE FUNCTION redeem_room_invite(p_token_hash text, p_user_id text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE invite_row record; BEGIN IF current_setting('app.user_id', true) IS DISTINCT FROM p_user_id THEN RAISE EXCEPTION 'invalid invite redemption context'; END IF; UPDATE room_invites SET uses = uses + 1 WHERE token_hash = p_token_hash AND revoked = false AND expires_at > now() AND uses < uses_limit RETURNING room_id, role INTO invite_row; IF NOT FOUND THEN RETURN NULL; END IF; INSERT INTO room_members (room_id, user_id, role) VALUES (invite_row.room_id, p_user_id, invite_row.role) ON CONFLICT (room_id, user_id) DO NOTHING; RETURN invite_row.room_id; END; $$;--> statement-breakpoint
